public protocol EnetNodeProtocol: AnyObject, Sendable {
    
    func acceptCall(call: UInt64) async throws 
    
    /**
     * Learns a peer's addresses from its `enet1…` ticket; returns its id.
     * Does NOT allow it in (`allowPeer`).
     */
    func addTicket(ticket: String) throws  -> String
    
    func allowPeer(peer: String) throws 
    
    func allowedPeers()  -> [String]
    
    func blobAdd(data: Data) async throws  -> EnetBlob
    
    func blobAddPath(path: String) async throws  -> EnetBlob
    
    func blobFetch(peer: String, hash: Data) async throws  -> Data
    
    func blobFetchTicket(ticket: String) async throws  -> Data
    
    func blobGet(hash: Data) async throws  -> Data?
    
    func endpointId()  -> String
    
    func getRecord(space: Data, key: String) throws  -> EnetRecord?
    
    func hangUp(call: UInt64) throws 
    
    /**
     * Subscribes to a space (32 bytes): its records arrive as
     * `EnetEvent.Record`, and its state is pulled from neighbours.
     */
    func joinSpace(space: Data, bootstrap: [String]) async throws 
    
    func leaveSpace(space: Data) throws 
    
    /**
     * The next event; `None` once the node is shut down.
     */
    func nextEvent() async  -> EnetEvent?
    
    /**
     * Waits until the home relay is connected (no-op without relays).
     */
    func online(timeoutMs: UInt64) async throws 
    
    func putRecord(space: Data, key: String, value: Data) async throws  -> EnetRecord
    
    func records(space: Data) throws  -> [EnetRecord]
    
    func revokePeer(peer: String) throws 
    
    /**
     * Sends and waits for the peer's acknowledgement.
     */
    func sendChat(peer: String, body: Data) async throws  -> EnetChatMessage
    
    /**
     * Sends one encoded audio frame (an Opus packet); returns its sequence number.
     */
    func sendFrame(call: UInt64, frame: Data) async throws  -> UInt32
    
    func setAccessPolicy(policy: EnetAccessPolicy?) 
    
    /**
     * Delivers every event to `listener` (replaces a previous one); `None`
     * stops the delivery (events queue for `nextEvent` again).
     */
    func setListener(listener: EnetListener?) 
    
    /**
     * Accept everyone (e.g. while a pairing QR code is on screen).
     */
    func setOpen(`open`: Bool) 
    
    /**
     * Closes every connection and stops serving.
     */
    func shutdown() async throws 
    
    /**
     * Rings the peer; `EnetEvent.CallAccepted` follows when it answers.
     */
    func startCall(peer: String) async throws  -> UInt64
    
    /**
     * The node's `enet1…` ticket (for a QR code or a link).
     */
    func ticket()  -> String
    
}
