extension EnetError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEnetError: FfiConverterRustBuffer {
    typealias SwiftType = EnetError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EnetError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Invalid(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Bind(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Connect(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Refused(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Crypto(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .NotFound(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Transport(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Closed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Panic(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EnetError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Invalid(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Bind(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Connect(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Refused(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Crypto(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotFound(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Transport(reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Closed(reason):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Panic(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


