// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.

public enum EnetEvent: Equatable, Hashable {
    
    case chat(from: String, message: EnetChatMessage
    )
    case record(record: EnetRecord
    )
    case callIncoming(call: UInt64, from: String
    )
    case callAccepted(call: UInt64
    )
    case callFrame(call: UInt64, seq: UInt32, data: Data
    )
    /**
     * `reason` = `local` | `remote` | `failed: …`.
     */
    case callEnded(call: UInt64, reason: String
    )
    case peerRefused(peer: String, alpn: String
    )





}

#if compiler(>=6)
extension EnetEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeEnetEvent: FfiConverterRustBuffer {
    typealias SwiftType = EnetEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> EnetEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .chat(from: try FfiConverterString.read(from: &buf), message: try FfiConverterTypeEnetChatMessage.read(from: &buf)
        )
        
        case 2: return .record(record: try FfiConverterTypeEnetRecord.read(from: &buf)
        )
        
        case 3: return .callIncoming(call: try FfiConverterUInt64.read(from: &buf), from: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .callAccepted(call: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 5: return .callFrame(call: try FfiConverterUInt64.read(from: &buf), seq: try FfiConverterUInt32.read(from: &buf), data: try FfiConverterData.read(from: &buf)
        )
        
        case 6: return .callEnded(call: try FfiConverterUInt64.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .peerRefused(peer: try FfiConverterString.read(from: &buf), alpn: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: EnetEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .chat(from,message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(from, into: &buf)
            FfiConverterTypeEnetChatMessage.write(message, into: &buf)
            
        
        case let .record(record):
            writeInt(&buf, Int32(2))
            FfiConverterTypeEnetRecord.write(record, into: &buf)
            
        
        case let .callIncoming(call,from):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(call, into: &buf)
            FfiConverterString.write(from, into: &buf)
            
        
        case let .callAccepted(call):
            writeInt(&buf, Int32(4))
            FfiConverterUInt64.write(call, into: &buf)
            
        
        case let .callFrame(call,seq,data):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(call, into: &buf)
            FfiConverterUInt32.write(seq, into: &buf)
            FfiConverterData.write(data, into: &buf)
            
        
        case let .callEnded(call,reason):
            writeInt(&buf, Int32(6))
            FfiConverterUInt64.write(call, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .peerRefused(peer,alpn):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(peer, into: &buf)
            FfiConverterString.write(alpn, into: &buf)
            
        }
    }
}


